package com.nequard.organization; import jakarta.persistence.*;import java.time.Instant;import java.util.UUID;@Entity @Table(name="organizations") public class Organization{@Id @GeneratedValue(strategy=GenerationType.UUID) UUID id;@Column(nullable=false)String name;@Column(nullable=false,unique=true)String slug;@Column(nullable=false)Instant createdAt=Instant.now();public UUID getId(){return id;}public String getName(){return name;}public void setName(String v){name=v;}public String getSlug(){return slug;}public void setSlug(String v){slug=v;}public Instant getCreatedAt(){return createdAt;}}